// ─── File: IoDecoratorDemo.java ───
// Single runnable file demonstrating the Decorator pattern via Java I/O streams.
package com.bank.io;

import java.io.*;
import java.util.zip.*;
import java.util.logging.*;

public class IoDecoratorDemo {
    private static final Logger log = Logger.getLogger(IoDecoratorDemo.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws IOException {
        String file = "balances.gz";

        log.info("=== WRITE: DataOutputStream -> Buffered -> GZIP -> File ===");
        // Decorator STACK on the output side. Each layer adds ONE concern.
        //   FileOutputStream   : raw bytes to disk (concrete component)
        //   GZIPOutputStream   : compress
        //   BufferedOutputStream: batch writes for speed
        //   DataOutputStream   : write typed primitives (writeUTF, writeDouble)
        try (DataOutputStream out = new DataOutputStream(
                     new BufferedOutputStream(
                     new GZIPOutputStream(
                     new FileOutputStream(file))))) {
            writeRecord(out, "SAV2001", 1000000.00);
            writeRecord(out, "CUR3001", 250000.00);
            out.writeUTF("END");
        } // one close() tears down the ENTIRE chain

        log.info("=== READ: DataInputStream -> Buffered -> GZIP -> File ===");
        // Mirror-image decorator STACK on the input side.
        try (DataInputStream in = new DataInputStream(
                     new BufferedInputStream(
                     new GZIPInputStream(
                     new FileInputStream(file))))) {
            while (true) {
                String id = in.readUTF();
                if ("END".equals(id)) break;
                double balance = in.readDouble();
                log.info(() -> "Read record -> account=" + id + " balance=Rs." + balance);
            }
        }
        log.info("Done — 3 decorator classes gave us compression + buffering + typed I/O.");
    }

    private static void writeRecord(DataOutputStream out, String id, double balance) throws IOException {
        out.writeUTF(id);       // typed write provided by DataOutputStream
        out.writeDouble(balance);
        log.fine(() -> "Wrote record for " + id);
    }
    // NOTE: Without Decorator, inheritance would need classes like
    // BufferedGzipDataFileInputStream for EVERY combination — subclass explosion.
}

// ─── Would be in util/BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
